entries[71101] = { ["name"] = "Glyphe 'Gegenzauber'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\n(0)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Gegenzauber' kann nun gewirkt werden, während Ihr andere Zauber wirkt oder kanalisiert, aber seine Abklingzeit ist um 4 Sek. erhöht." }
entries[71102] = { ["name"] = "Glyphe 'Endgültige Entschlossenheit'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nAußerhalb von Arenen und Schlachtfeldern:\n[ Gebrechen : Erhöht die Dauer der Zauber 'Instabiles Gebrechen', 'Verderbnis' und 'Agonie' ] [ Dämonologie : Erhöht die Dauer der Zauber 'Verderbnis' und 'Verdammnis' ] [ Zerstörung : Erhöht die Dauer der Zauber 'Verderbnis', 'Verdammnis' und 'Agonie' ] um 50% und verringert ihren Schaden um 20%.\n\nInnerhalb von Arenen und Schlachtfeldern:\nEuer Zauber 'Erbarmungslose Entschlossenheit' kann nicht mehr aktiviert werden, sondern gewährt 10% Schadensverringerung für alle Quellen." }
